def extract(dest=None, quiet=False):
    """Unpack every artifact into dest (default ./models_v1), sha-verified."""
    root = Path(dest) if dest else Path(__file__).resolve().parent / DEFAULT_DEST
    written = []
    for rel, (algo, size, sha, chunks) in FILES.items():
        data = base64.b85decode("".join(chunks))
        if algo == "xz":
            data = lzma.decompress(data)
        if len(data) != size:
            raise SystemExit(
                f"corrupt bundle: {rel} size {len(data)} != {size} - "
                "re-download this file")
        if hashlib.sha256(data).hexdigest() != sha:
            raise SystemExit(
                f"corrupt bundle: {rel} sha256 mismatch - re-download")
        out = root / rel
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_bytes(data)
        written.append(rel)
        if not quiet:
            print(f"  + {rel}  ({size:,} B)")
    if not quiet:
        print(f"{len(written)} artifacts -> {root}")
    return written


if __name__ == "__main__":
    _dest = None
    if len(sys.argv) >= 3 and sys.argv[1] == "--dest":
        _dest = sys.argv[2]
    extract(_dest)
